import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"文件系统","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/filesystems.md","filePath":"zh/manual/filesystems.md"}'),d={name:"zh/manual/filesystems.md"};function o(c,e,p,i,l,h){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="文件系统" tabindex="-1">文件系统 <a class="header-anchor" href="#文件系统" aria-label="Permalink to &quot;文件系统&quot;">​</a></h1><h2 id="vfs-层" tabindex="-1">VFS 层 <a class="header-anchor" href="#vfs-层" aria-label="Permalink to &quot;VFS 层&quot;">​</a></h2><p>内核 VFS 作为前端对接四种文件系统实现：</p><table tabindex="0"><thead><tr><th>类型</th><th>读</th><th>写</th><th>适用场景</th></tr></thead><tbody><tr><td>ramfs</td><td>是</td><td>是</td><td>ISO 根——一切都在 RAM 中</td></tr><tr><td>FAT32</td><td>是</td><td>是</td><td>与所有操作系统交换数据</td></tr><tr><td>exFAT</td><td>是</td><td>是</td><td>大容量可移动卷</td></tr><tr><td>ext4</td><td>读*</td><td>否*</td><td>检视 Linux 磁盘</td></tr></tbody></table><p>（*）本版本中 ext4 这一分支以挂载/读取为主。</p><h2 id="日常文件操作" tabindex="-1">日常文件操作 <a class="header-anchor" href="#日常文件操作" aria-label="Permalink to &quot;日常文件操作&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; files                  the wizard: ls / tree / df+du / cp / mv /</span></span>
<span class="line"><span>                            rm (confirmed) / edit / stat+chmod</span></span>
<span class="line"><span>ush&gt; files edit /etc/opencube.conf</span></span></code></pre></div><p>也可以直接使用经典程序——<code>ls</code>、<code>tree</code>、<code>df</code>、<code>du</code>、<code>cp</code>、<code>mv</code>、<code>rm</code>、<code>edit</code>、<code>stat</code>、<code>chmod</code>、<code>cat</code>、<code>mkdir</code>、<code>ln</code>、<code>wc</code>、<code>grep</code>、<code>head</code>、<code>tail</code>、<code>sort</code>、<code>awk</code>。它们是普通的注册表程序；<code>files</code> 是进入同一批二进制的第二扇门。</p><h2 id="格式化与挂载" tabindex="-1">格式化与挂载 <a class="header-anchor" href="#格式化与挂载" aria-label="Permalink to &quot;格式化与挂载&quot;">​</a></h2><p><code>disk-tool</code> 带你走完整条流程：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; disk-tool              -&gt; list devices (lsblk)</span></span>
<span class="line"><span>                           -&gt; partition table (parted)</span></span>
<span class="line"><span>                           -&gt; create a filesystem (mkfs.fat32 / exfat /</span></span>
<span class="line"><span>                              ext4 - the device name is asked, retyped</span></span>
<span class="line"><span>                              and confirmed)</span></span>
<span class="line"><span>                           -&gt; mount manager (list / mount / umount /</span></span>
<span class="line"><span>                              fatmount / fatstat)</span></span></code></pre></div><p>经典形式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; mkfs.fat32 hd0p1       (destroys data - no wizard, no extra prompt)</span></span>
<span class="line"><span>ush&gt; mount fat32 hd0p1 /mnt</span></span>
<span class="line"><span>ush&gt; umount /mnt</span></span></code></pre></div><p><code>fatmount</code> 是 FAT 专用的便捷命令（自动探测 FAT 卷），<code>fatstat</code> 报告 FAT 统计信息，<code>fsck</code> 检查文件系统。</p><h2 id="etc-卷" tabindex="-1">/etc 卷 <a class="header-anchor" href="#etc-卷" aria-label="Permalink to &quot;/etc 卷&quot;">​</a></h2><p><code>/etc/opencube.conf</code> 承载持久化配置（更新 URL、自动检查、在线更新、shell 语言）。ISO 引导时它位于 RAM 中，重启后重置；在已安装的系统上（或接入 <code>etc.img</code> 磁盘时）则持久保存：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; config list</span></span>
<span class="line"><span>ush&gt; config get update_url</span></span>
<span class="line"><span>ush&gt; config set online_update no</span></span>
<span class="line"><span>ush&gt; config restore         (back to defaults)</span></span></code></pre></div><h2 id="路径与当前目录" tabindex="-1">路径与当前目录 <a class="header-anchor" href="#路径与当前目录" aria-label="Permalink to &quot;路径与当前目录&quot;">​</a></h2><p><code>cd</code>、<code>pwd</code>、<code>ls</code> 的行为与 Unix 同名命令一致；路径以 <code>/</code> 分隔，是以 ramfs 根为起点的绝对路径。编辑器原地写回；<code>cp</code>/<code>mv</code>/<code>rm</code>/<code>chmod</code>/<code>stat</code> 采用直观的形式（<code>chmod &lt;octal&gt; &lt;path&gt;</code>）。</p><h2 id="运行中系统里各路径的内容" tabindex="-1">运行中系统里各路径的内容 <a class="header-anchor" href="#运行中系统里各路径的内容" aria-label="Permalink to &quot;运行中系统里各路径的内容&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/            ramfs root (the ISO content)</span></span>
<span class="line"><span>/etc         the config volume (persisted when etc.img is attached)</span></span>
<span class="line"><span>/mnt, /media conventional mount points</span></span>
<span class="line"><span>/bin, /lib   the embedded program registry is in-kernel; these</span></span>
<span class="line"><span>             paths exist for the dynamic-linker leg (ld.so, libfoo)</span></span></code></pre></div>`,21)])])}const m=a(d,[["render",o]]);export{u as __pageData,m as default};
